**Parser and Validator for Untrusted YAML-like Configuration**
===========================================================

**Parser**
--------

The parser will recursively traverse the input YAML-like string and check for the following conditions:

*   Alias bombs: If a key is used as a reference to another key, it will be rejected.
*   Path traversal: If a key is used as a reference to a nested key, it will be rejected.
*   Duplicate keys: If a key is used multiple times, it will be rejected.
*   Schema ambiguity: If a key is used as a reference to a schema that is not defined, it will be rejected.

**Validator**
------------

The validator will check the parsed configuration against a schema defined in a separate file. If the configuration is valid, it will be returned as a JSON object. If the configuration is invalid, it will be rejected as a JSON object.

**Code**
------

### parser.js
```javascript
const yaml = require('js-yaml');

class Parser {
  constructor(schema) {
    this.schema = schema;
  }

  parse(yamlString) {
    const config = yaml.safeLoad(yamlString);
    if (!config) {
      throw new Error('Invalid YAML string');
    }

    this.validate(config);

    return config;
  }

  validate(config) {
    const keys = Object.keys(config);

    // Check for alias bombs
    for (const key of keys) {
      if (this.isAlias(key, config)) {
        throw new Error(`Alias bomb detected at key '${key}'`);
      }
    }

    // Check for path traversal
    for (const key of keys) {
      if (this.isPathTraversal(key, config)) {
        throw new Error(`Path traversal detected at key '${key}'`);
      }
    }

    // Check for duplicate keys
    for (const key of keys) {
      if (this.isDuplicateKey(key, config)) {
        throw new Error(`Duplicate key '${key}' found`);
      }
    }

    // Check for schema ambiguity
    for (const key of keys) {
      if (this.isSchemaAmbiguity(key, config)) {
        throw new Error(`Schema ambiguity detected at key '${key}'`);
      }
    }
  }

  isAlias(key, config) {
    const alias = config[key];
    if (typeof alias === 'object' && alias !== null) {
      return true;
    }
    return false;
  }

  isPathTraversal(key, config) {
    const path = config[key];
    if (typeof path === 'object' && path !== null) {
      if (path[0] === '[' && path[path.length - 1] === ']') {
        return true;
      }
      return false;
    }
    return false;
  }

  isDuplicateKey(key, config) {
    const duplicateKey = config[key];
    if (typeof duplicateKey === 'object' && duplicateKey !== null) {
      return true;
    }
    return false;
  }

  isSchemaAmbiguity(key, config) {
    const schema = config[key];
    if (typeof schema === 'object' && schema !== null) {
      if (schema.type === 'object' && schema.properties) {
        return true;
      }
      return false;
    }
    return false;
  }
}

module.exports = Parser;
```

### validator.js
```javascript
const Parser = require('./parser');

class Validator {
  constructor(schema) {
    this.schema = schema;
  }

  validate(config) {
    const parser = new Parser(this.schema);
    return parser.parse(config);
  }
}

module.exports = Validator;
```

